    "p.a1-04.1": "Ho fame.",
    "p.a1-04.2": "Ho sete.",
    "p.a1-04.3": "Vorrei un caffè, per favore.",
    "p.a1-04.4": "Cosa vuoi da bere?",
    "p.a1-04.5": "Un bicchiere d'acqua, per favore.",
    "p.a1-04.6": "È delizioso!",
    "p.a1-04.7": "Non mangio carne.",
    "p.a1-04.8": "Cosa c'è per cena?",
    "p.a1-04.9": "Buon appetito!",
    "p.a1-04.10": "Vuoi tè o caffè?",
    "p.a1-04.11": "Bevo molta acqua.",
    "p.a1-04.12": "Con latte e zucchero, per favore.",
    "s.a1-04.1": "A colazione mangio pane con formaggio e un uovo.",
    "s.a1-04.2": "Mio fratello beve il caffè ogni mattina.",
    "s.a1-04.3": "A cena mangiamo pesce e riso.",
    "s.a1-04.4": "Vuoi una mela o un pomodoro?",
    "s.a1-04.5": "La zuppa è calda e molto buona.",
    "s.a1-04.6": "Lei mangia molta frutta e verdura.",
    "s.a1-04.7": "Ho sete; voglio un bicchiere di succo.",
    "s.a1-04.8": "Bevono vino a pranzo e birra a cena.",
    "s.a1-04.9": "I miei figli non bevono latte.",
    "s.a1-04.10": "L'insalata di pollo è per mia madre.",
    "s.a1-04.11": "C'è zucchero nel tè?",
    "s.a1-04.12": "Ho fame, ma non c'è cibo a casa.",
    "d.a1-04.1": "Buongiorno! Hai fame?",
    "d.a1-04.2": "Sì, molta. Cosa c'è per colazione?",
    "d.a1-04.3": "Pane, formaggio, uova e pomodori.",
    "d.a1-04.4": "Ottimo. C'è il caffè?",
    "d.a1-04.5": "Sì. Con il latte?",
    "d.a1-04.6": "Con il latte, senza zucchero, per favore.",
    "d.a1-04.7": "Vuoi anche del succo?",
    "d.a1-04.8": "No, grazie. Solo acqua. Ho molta sete.",
    "d.a1-04.9": "Ecco. Buon appetito!",
    "d.a1-04.10": "Grazie! Il formaggio è delizioso.",
    "m.a1-04": "A colazione mangio ... e bevo ... . A pranzo mangio ... . A cena mangiamo ... . Non mangio ... .",

