    "d.a1-05.1": "Buonasera. Un tavolo per due?",
    "d.a1-05.2": "Sì, per favore. E il menù.",
    "d.a1-05.3": "Ecco a Lei. Qualcosa da bere?",
    "d.a1-05.4": "Una bottiglia d'acqua e un bicchiere di vino, per favore.",
    "d.a1-05.5": "E da mangiare? Oggi il pesce è molto buono.",
    "d.a1-05.6": "Cosa mi consiglia con il pesce?",
    "d.a1-05.7": "Riso o un'insalata.",
    "d.a1-05.8": "Il pesce con il riso, per favore. E per dolce, torta al cioccolato.",
    "d.a1-05.9": "Benissimo. Desidera altro?",
    "d.a1-05.10": "No, grazie. Il conto, per favore. Posso pagare con la carta?",
    "d.a1-05.11": "Certo. Ecco a Lei.",
    "m.a1-05": "Buonasera. Un tavolo per ... , per favore. Vorrei ... e ... da bere. Per dolce, ... . Il conto, per favore.",

