    "p.a1-08.11": "Usciamo insieme!",
    "p.a1-08.12": "Sei libero stasera?",
    "s.a1-08.1": "Mi sveglio alle sei e mi alzo alle sei e mezza.",
    "s.a1-08.2": "Prima del lavoro mio padre legge un libro.",
