    "d.a1-08.7": "Faccio sport, poi cucino la cena.",
    "d.a1-08.8": "Io finisco di lavorare alle sei e torno a casa molto stanco.",
    "d.a1-08.9": "Esci nel fine settimana?",
    "d.a1-08.10": "Sì, il venerdì sera con gli amici. Sei libero venerdì?",
    "d.a1-08.11": "Sì! Usciamo insieme.",
    "m.a1-08": "Ogni giorno mi alzo alle ... . Io ... alle ... . Poi ... . Dopo il lavoro ... . La sera ... e vado a letto alle ... .",

