    "p.a1-09.1": "Benvenuto a casa mia!",
    "p.a1-09.2": "C'è una cucina grande.",
    "p.a1-09.3": "Ci sono tre camere da letto.",
    "p.a1-09.4": "Dov'è il bagno?",
    "p.a1-09.5": "Le chiavi sono sul tavolo.",
    "p.a1-09.6": "Abito al terzo piano.",
    "p.a1-09.7": "C'è l'ascensore?",
    "p.a1-09.8": "Quanto costa l'affitto?",
    "p.a1-09.9": "Chiudi la porta, per favore.",
    "p.a1-09.10": "Apri la finestra, fa caldo.",
    "p.a1-09.11": "Fai come se fossi a casa tua.",
    "p.a1-09.12": "L'appartamento è in affitto.",
    "s.a1-09.1": "Il mio appartamento ha due camere da letto e una piccola cucina.",
    "s.a1-09.2": "In soggiorno ci sono un divano e una lampada.",
    "s.a1-09.3": "Le mie chiavi sono sotto la sedia.",
    "s.a1-09.4": "Non c'è l'ascensore; prendiamo le scale.",
    "s.a1-09.5": "Affittiamo un appartamento nuovo con un grande balcone.",
    "s.a1-09.6": "Il bagno è accanto alla camera da letto.",
    "s.a1-09.7": "Il mio vicino è un signore anziano e tranquillo.",
    "s.a1-09.8": "Metto il libro sul tavolo e la borsa sotto.",
    "s.a1-09.9": "La casa ha un piccolo giardino e due porte.",
    "s.a1-09.10": "Per favore, apri la porta e chiudi la finestra.",
    "s.a1-09.11": "Il divano è molto comodo, ma il letto è vecchio.",
    "s.a1-09.12": "In cucina ci sono un tavolo e quattro sedie?",
    "d.a1-09.1": "Buon pomeriggio, Tamar. Entri, questo è l'appartamento.",
    "d.a1-09.2": "Grazie. Oh, il soggiorno è grande!",
    "d.a1-09.3": "Sì, ed è molto tranquillo. Ecco la cucina.",
    "d.a1-09.4": "È nuova! E quante camere da letto ci sono?",
    "d.a1-09.5": "Due camere da letto e un bagno. Le camere sono piccole ma comode.",
    "d.a1-09.6": "C'è un balcone?",
    "d.a1-09.7": "Sì, un piccolo balcone dietro la cucina.",
    "d.a1-09.8": "E l'ascensore? È il quarto piano.",
    "d.a1-09.9": "No, non c'è l'ascensore, solo le scale.",
    "d.a1-09.10": "Mmm. Quanto costa l'affitto?",
    "d.a1-09.11": "Ottocento al mese, acqua inclusa.",
    "d.a1-09.12": "Grazie, signor Levi. Devo pensarci.",
    "m.a1-09": "Abito in un ... al ... piano. Ci sono ... stanze. In soggiorno c'è ... . La cucina è ... . Non c'è ... .",

