    "p.a1-10.1": "Che tempo fa?",
    "p.a1-10.2": "C'è il sole e fa caldo.",
    "p.a1-10.3": "Piove.",
    "p.a1-10.4": "In inverno fa freddo.",
    "p.a1-10.5": "Mi piace nuotare nel mare.",
    "p.a1-10.6": "Non mi piace la pioggia.",
    "p.a1-10.7": "Ti piace ballare?",
    "p.a1-10.8": "Cosa fai nel tempo libero?",
    "p.a1-10.9": "Andiamo al cinema!",
    "p.a1-10.10": "Perché no?",
    "p.a1-10.11": "Preferisco la montagna.",
    "p.a1-10.12": "Che bella giornata!",
    "s.a1-10.1": "In estate fa caldo e andiamo in spiaggia.",
    "s.a1-10.2": "In inverno c'è la neve in montagna.",
    "s.a1-10.3": "Oggi il cielo è blu e non ci sono nuvole.",
    "s.a1-10.4": "A me piace il mare, ma mia sorella preferisce la montagna.",
    "s.a1-10.5": "Perché ti piace l'autunno? Perché il tempo è bello.",
    "s.a1-10.6": "Il mio hobby è la musica: canto e ballo.",
    "s.a1-10.7": "Incontriamo gli amici al bar ogni fine settimana.",
    "s.a1-10.8": "Piove; guardiamo la televisione a casa.",
    "s.a1-10.9": "La primavera è una stagione bella e calda.",
    "s.a1-10.10": "Viaggiano molto perché amano le città interessanti.",
    "s.a1-10.11": "Oggi il tempo è brutto: vento, pioggia e freddo.",
    "s.a1-10.12": "Vuoi andare alla festa sabato?",
    "d.a1-10.1": "Shira, che tempo fa domani?",
    "d.a1-10.2": "Sole e caldo. Una bella giornata per la spiaggia!",
    "d.a1-10.3": "Non mi piace la spiaggia. Preferisco la montagna.",
    "d.a1-10.4": "Perché?",
    "d.a1-10.5": "Perché non mi piace nuotare e amo camminare.",
    "d.a1-10.6": "Ok. E la sera? C'è una festa a casa di Dan.",
    "d.a1-10.7": "Ottimo, mi piace ballare! A che ora?",
    "d.a1-10.8": "Alle nove. Prima della festa ci incontriamo al bar, ok?",
    "d.a1-10.9": "Perfetto. E domenica?",
    "d.a1-10.10": "Domenica piove. Cinema?",
    "d.a1-10.11": "Sì! Amo il cinema quando il tempo è brutto.",
    "m.a1-10": "La mia stagione preferita è ... perché ... . In ... fa ... . Nel tempo libero mi piace ... e ... . Non mi piace ... .",

