    "p.a2-04.1": "Che lavoro fai?",
    "p.a2-04.2": "Lavoro come ingegnere.",
    "p.a2-04.3": "Lavoro per una grande azienda.",
    "p.a2-04.4": "Cerco lavoro.",
    "p.a2-04.5": "Ho una riunione alle dieci.",
    "p.a2-04.6": "Quanto spesso viaggi per lavoro?",
    "p.a2-04.7": "Di solito finisco alle sei.",
    "p.a2-04.8": "Non lavoro mai nel fine settimana.",
    "p.a2-04.9": "Lo stipendio è buono.",
    "p.a2-04.10": "Ho cinque anni di esperienza.",
    "p.a2-04.11": "Al momento sono disoccupato.",
    "p.a2-04.12": "Buona fortuna per il colloquio!",
    "s.a2-04.1": "Mio padre è autista e mia madre è infermiera.",
    "s.a2-04.2": "Arrivo sempre in ufficio prima del mio capo.",
    "s.a2-04.3": "Lavora come avvocato e guadagna un buono stipendio.",
    "s.a2-04.4": "L'azienda assume dieci nuovi dipendenti ogni anno.",
    "s.a2-04.5": "Di solito abbiamo una riunione il lunedì mattina.",
    "s.a2-04.6": "Il mio collega a volte lavora da casa.",
    "s.a2-04.7": "Si è candidato per il posto e ha un colloquio domani.",
    "s.a2-04.8": "Lo chef mangia raramente al ristorante.",
    "s.a2-04.9": "Mio nonno è in pensione, ma è sempre occupato.",
    "s.a2-04.10": "Il lavoro dell'agricoltore è difficile ma interessante.",
    "s.a2-04.11": "La giornalista viaggia spesso all'estero per lavoro.",
    "s.a2-04.12": "Ho un contratto di un anno con la nuova azienda.",
    "d.a2-04.1": "Buongiorno, Roni. Prego, si sieda. Mi parli della sua esperienza.",
    "d.a2-04.2": "Grazie. Ho lavorato per tre anni come ingegnere in una piccola azienda.",
    "d.a2-04.3": "Perché vuole lavorare con noi?",
    "d.a2-04.4": "Perché la vostra azienda è grande e i progetti sono interessanti.",
    "d.a2-04.5": "Lavora spesso in squadra?",
    "d.a2-04.6": "Sì, sempre. Mi piace lavorare con i colleghi.",
    "d.a2-04.7": "Può lavorare a volte nel fine settimana?",
    "d.a2-04.8": "A volte sì, ma non ogni settimana.",
    "d.a2-04.9": "Bene. Lo stipendio è di tremila al mese, con un contratto di un anno.",
    "d.a2-04.10": "Mi sembra buono. Quando comincio?",
    "d.a2-04.11": "La chiamiamo la settimana prossima. Grazie per essere venuto!",
    "m.a2-04": "Sono ... . Lavoro per ... da ... . Di solito ... e spesso ... . Non ... mai. Guadagno ... .",

