    "p.a2-05.1": "Non capisco.",
    "p.a2-05.2": "Può ripetere, per favore?",
    "p.a2-05.3": "Cosa significa questa parola?",
    "p.a2-05.4": "Come si dice questo nella tua lingua?",
    "p.a2-05.5": "Ho un esame venerdì.",
    "p.a2-05.6": "Ho superato l'esame!",
    "p.a2-05.7": "Aprite i libri a pagina dieci.",
    "p.a2-05.8": "Puoi spiegarlo di nuovo?",
    "p.a2-05.9": "Ho fatto un errore.",
    "p.a2-05.10": "È giusto?",
    "p.a2-05.11": "Ho fatto i compiti ieri.",
    "p.a2-05.12": "Sai la risposta?",
    "s.a2-05.1": "Ieri sono andato in biblioteca e ho studiato per tre ore.",
    "s.a2-05.2": "L'insegnante ha spiegato la lezione e noi abbiamo fatto domande.",
    "s.a2-05.3": "Ho dimenticato il quaderno e la penna a casa.",
    "s.a2-05.4": "Ha avuto un buon voto in matematica, ma è stata bocciata in storia.",
    "s.a2-05.5": "La settimana scorsa abbiamo imparato venti parole nuove nel corso.",
    "s.a2-05.6": "La mia materia preferita a scuola erano le scienze.",
    "s.a2-05.7": "Hai fatto i compiti? No, non ho avuto tempo.",
    "s.a2-05.8": "Sa la risposta, ma non capisce la domanda.",
    "s.a2-05.9": "Gli studenti erano in aula e l'insegnante era in ritardo.",
    "s.a2-05.10": "Ho scritto la risposta sbagliata a pagina cinque.",
    "s.a2-05.11": "All'università ho studiato storia per quattro anni.",
    "s.a2-05.12": "Per favore, ripeti la parola e scrivila con la matita.",
    "d.a2-05.1": "Hila, com'è andato l'esame?",
    "d.a2-05.2": "Difficile! Non ho capito l'ultima domanda.",
    "d.a2-05.3": "Quella di storia? Io sapevo la risposta, credo.",
    "d.a2-05.4": "Ho studiato tutta la notte, ma ho dimenticato le date.",
    "d.a2-05.5": "Sei andata a lezione lunedì? L'insegnante ha spiegato tutto.",
    "d.a2-05.6": "No, ero malata e avevo un appuntamento dal medico.",
    "d.a2-05.7": "Posso darti il mio quaderno. Ci sono tutte le risposte.",
    "d.a2-05.8": "Grazie! Hai fatto molti errori?",
    "d.a2-05.9": "Due o tre, credo. La parte di matematica era facile.",
    "d.a2-05.10": "Facile per te! Quando riceviamo i voti?",
    "d.a2-05.11": "La settimana prossima. Dai, andiamo in biblioteca.",
    "m.a2-05": "A scuola mi piaceva ... , ma ... era difficile. La settimana scorsa sono andato a ... e ho imparato ... . Ho fatto ... errori. Non ho capito ... .",

