    "p.a2-06.1": "Cosa ti metti per la festa?",
    "p.a2-06.2": "Posso provarlo?",
    "p.a2-06.3": "Ti sta benissimo.",
    "p.a2-06.4": "È troppo grande per me.",
    "p.a2-06.5": "Che aspetto ha?",
    "p.a2-06.6": "Ha i capelli lunghi e scuri.",
    "p.a2-06.7": "È più alto di me.",
    "p.a2-06.8": "Questo è migliore di quello.",
    "p.a2-06.9": "È la donna più elegante dell'ufficio.",
    "p.a2-06.10": "Porta gli occhiali.",
    "p.a2-06.11": "Prendi un cappotto, fuori fa freddo.",
    "p.a2-06.12": "Stai benissimo!",
    "s.a2-06.1": "Oggi indosso i jeans, una maglietta bianca e una giacca.",
    "s.a2-06.2": "Mia sorella è più bassa di me, ma è più forte.",
    "s.a2-06.3": "Questo vestito è più elegante della gonna.",
    "s.a2-06.4": "È un uomo alto e magro con i capelli biondi e gli occhiali.",
    "s.a2-06.5": "Queste scarpe sono migliori di quelle, ma più care.",
    "s.a2-06.6": "In inverno indossiamo un cappotto, un cappello e una sciarpa.",
    "s.a2-06.7": "Mia nonna è la persona più gentile della famiglia.",
    "s.a2-06.8": "Ho provato i pantaloni, ma non mi andavano bene.",
    "s.a2-06.9": "Il tempo oggi è peggiore di ieri.",
    "s.a2-06.10": "I calzini neri sono più economici di quelli rossi.",
    "s.a2-06.11": "Le piace la moda e indossa sempre bei vestiti.",
    "s.a2-06.12": "Mio fratello è lo studente più bello della sua classe.",
    "d.a2-06.1": "Michal, chi è la donna accanto al tuo capo?",
    "d.a2-06.2": "Quale? Quella alta con i capelli lunghi e scuri?",
    "d.a2-06.3": "No, quella più bassa con gli occhiali e il vestito rosso.",
    "d.a2-06.4": "Ah, quella è Dana, la nostra nuova collega. È molto gentile.",
    "d.a2-06.5": "È molto elegante. Mi piace la sua giacca.",
    "d.a2-06.6": "Sì, ama la moda. Indossa sempre vestiti migliori dei miei!",
    "d.a2-06.7": "E chi è l'uomo con i capelli biondi e la camicia blu?",
    "d.a2-06.8": "Quello è suo marito. È più grande di lei, credo.",
    "d.a2-06.9": "Sembra una persona simpatica.",
    "d.a2-06.10": "Lo è. Vieni, te lo presento.",
    "m.a2-06": "Il mio amico ... è alto / basso e ha i capelli ... . Di solito indossa ... . È più alto di me, ma io sono più ... di lui. È la persona più ... che conosco.",

