    "w.a2-07.famous": "famoso",
    "p.a2-07.1": "Indovina cosa mi è successo!",
    "p.a2-07.2": "C'era una volta...",
    "p.a2-07.3": "Cosa è successo dopo?",
    "p.a2-07.4": "All'improvviso, le luci si sono spente.",
    "p.a2-07.5": "Sono nato nel 1990.",
    "p.a2-07.6": "Sono cresciuto in un piccolo paese.",
    "p.a2-07.7": "Per fortuna, nessuno si è fatto male.",
    "p.a2-07.8": "Stai scherzando!",
    "p.a2-07.9": "Non ci potevo credere.",
    "p.a2-07.10": "Alla fine, è andato tutto bene.",
    "p.a2-07.11": "Mentre dormivo, il telefono ha suonato.",
    "p.a2-07.12": "Raccontami tutta la storia.",
    "s.a2-07.1": "Quando ero bambino, abitavamo vicino al mare.",
    "s.a2-07.2": "Prima ho perso le chiavi, poi le ho trovate nella borsa.",
    "s.a2-07.3": "Mentre mangiavamo, mio fratello ha raccontato una lunga storia.",
    "s.a2-07.4": "All'improvviso è caduta e si è rotta un braccio.",
    "s.a2-07.5": "I miei genitori si sono sposati trent'anni fa.",
    "s.a2-07.6": "Ha detto che aveva visto una persona famosa all'aeroporto.",
    "s.a2-07.7": "Abbiamo vinto e tutti hanno riso e cantato.",
    "s.a2-07.8": "C'è stato un incidente sulla strada, ma per fortuna nessuno si è fatto male.",
    "s.a2-07.9": "È stata un'avventura meravigliosa dall'inizio alla fine.",
    "s.a2-07.10": "Purtroppo, quando siamo arrivati, la festa era già finita.",
    "s.a2-07.11": "Il bambino ha pianto tutta la notte e siamo ancora stanchi.",
    "s.a2-07.12": "In quel momento ho capito che era una festa a sorpresa.",
    "d.a2-07.1": "Nonna, raccontami una storia della tua infanzia.",
    "d.a2-07.2": "Una volta, quando avevo otto anni, sono andata in spiaggia con mio fratello.",
    "d.a2-07.3": "Solo voi due? Senza i vostri genitori?",
    "d.a2-07.4": "Sì! Mentre nuotavamo, all'improvviso ha cominciato a piovere.",
    "d.a2-07.5": "E poi cosa è successo?",
    "d.a2-07.6": "Siamo corsi a casa, ma io sono caduta e ho perso una scarpa.",
    "d.a2-07.7": "Oh no! L'hai trovata?",
    "d.a2-07.8": "No, purtroppo. Mia madre era arrabbiata, ma poi ha riso.",
    "d.a2-07.9": "E tuo fratello?",
    "d.a2-07.10": "Racconta ancora questa storia a ogni cena di famiglia!",
    "d.a2-07.11": "Adoro le tue storie, nonna.",
    "m.a2-07": "... scorso ero ... quando all'improvviso ... . Prima ho ... , poi ho ... . Per fortuna, ... . Alla fine ... .",

