    "p.a2-08.1": "Cosa fai il prossimo fine settimana?",
    "p.a2-08.2": "Vado a trovare i miei genitori.",
    "p.a2-08.3": "Ti piacerebbe venire al mio compleanno?",
    "p.a2-08.4": "Mi piacerebbe molto!",
    "p.a2-08.5": "Mi dispiace, non posso. Ho altri piani.",
    "p.a2-08.6": "Forse la prossima volta.",
    "p.a2-08.7": "A presto!",
    "p.a2-08.8": "Lo spero.",
    "p.a2-08.9": "Cosa farai dopo il corso?",
    "p.a2-08.10": "Ti chiamo più tardi.",
    "p.a2-08.11": "Sei pronto?",
    "p.a2-08.12": "È una promessa!",
    "s.a2-08.1": "L'anno prossimo studierò all'estero.",
    "s.a2-08.2": "Se domani piove, resteremo a casa.",
    "s.a2-08.3": "Mia sorella si sposerà a giugno; stiamo organizzando il matrimonio.",
    "s.a2-08.4": "Presto si trasferiranno in un appartamento più grande.",
    "s.a2-08.5": "Risparmio soldi perché voglio viaggiare in Giappone.",
    "s.a2-08.6": "Probabilmente festeggeremo il suo compleanno al ristorante.",
    "s.a2-08.7": "Ha deciso di diventare medico quando aveva dieci anni.",
    "s.a2-08.8": "Verrai al concerto con noi venerdì?",
    "s.a2-08.9": "Il mio sogno è avere la mia azienda un giorno.",
    "s.a2-08.10": "Prometto che cercherò di arrivare presto.",
    "s.a2-08.11": "Qual è la data del matrimonio? Il venti maggio.",
    "s.a2-08.12": "È impossibile finire il progetto questa settimana.",
    "d.a2-08.1": "Nir, cosa fai sabato prossimo?",
    "d.a2-08.2": "Non lo so ancora. Perché?",
    "d.a2-08.3": "È il mio compleanno e faccio una festa a casa. Ti piacerebbe venire?",
    "d.a2-08.4": "Mi piacerebbe molto! A che ora?",
    "d.a2-08.5": "Alle otto. Io cucino e Maya porterà la musica.",
    "d.a2-08.6": "Ottimo. Posso portare qualcosa?",
    "d.a2-08.7": "Forse una torta? Se hai tempo.",
    "d.a2-08.8": "Certamente. Farò una torta al cioccolato. Quante persone vengono?",
    "d.a2-08.9": "Probabilmente quindici. E il mese prossimo festeggeremo di nuovo: il matrimonio di mia sorella!",
    "d.a2-08.10": "Wow, congratulazioni! Allora ci vediamo sabato.",
    "m.a2-08": "... prossimo ho intenzione di ... . Probabilmente ... . Se ho tempo, ... . Il mio sogno è ... . Spero di ... presto.",

