    "d.b1-08.1": "Grazie per essere venuto. Mi parli della sua esperienza.",
    "d.b1-08.2": "Ho lavorato nelle vendite per cinque anni, soprattutto gestendo i conti dei clienti.",
    "d.b1-08.3": "Perché è interessato a lasciare il suo attuale datore di lavoro?",
    "d.b1-08.4": "Cerco una nuova sfida e più responsabilità.",
    "d.b1-08.5": "Quali abilità porterebbe in questa posizione?",
    "d.b1-08.6": "Sono bravo a negoziare, e i miei colleghi dicono che sono molto affidabile.",
    "d.b1-08.7": "Il lavoro prevede alcuni straordinari nei periodi intensi. È un problema?",
    "d.b1-08.8": "Per niente, purché siano pianificati in anticipo.",
    "d.b1-08.9": "Offriamo formazione, buoni benefit e una possibilità di promozione entro un anno.",
    "d.b1-08.10": "Sembra un'ottima opportunità. Quando pensate di decidere?",
    "d.b1-08.11": "Ci faremo sentire entro la fine della settimana prossima.",
    "m.b1-08": "Scrivo per candidarmi alla posizione di ... . Ho ... anni di esperienza in ... . Sono bravo a ... e mi interessa ... . Resto in attesa di ... .",

