    "p.b2-01.1": "Vorrei aver studiato di più a scuola.",
    "p.b2-01.2": "Se solo avessi più tempo per ripassare.",
    "p.b2-01.3": "Sta facendo un master in biologia.",
    "p.b2-01.4": "La scadenza per il saggio è lunedì.",
    "p.b2-01.5": "Ha abbandonato gli studi al secondo anno.",
    "p.b2-01.6": "Non riesco a concentrarmi con tutto questo rumore.",
    "p.b2-01.7": "Imparare a memoria non è lo stesso che capire.",
    "p.b2-01.8": "Ha ottenuto una borsa di studio completa.",
    "p.b2-01.9": "A meno che non ti iscriva entro venerdì, perderai il posto.",
    "p.b2-01.10": "Non è mai troppo tardi per tornare all'università.",
    "p.b2-01.11": "La pratica rende perfetti.",
    "s.b2-01.1": "Se avessi ricevuto una borsa di studio, avrei studiato all'estero.",
    "s.b2-01.2": "Vorrei che il programma di studi includesse più pensiero critico.",
    "s.b2-01.3": "Ha preso appunti con cura in modo da poter ripassare prima dell'esame.",
    "s.b2-01.4": "A meno che gli studenti non acquisiscano disciplina presto, fanno fatica all'università.",
    "s.b2-01.5": "Ha abbandonato la laurea perché le tasse universitarie erano troppo alte.",
    "s.b2-01.6": "Se solo le lezioni fossero registrate, potrei guardarle più tardi.",
    "s.b2-01.7": "I bambini dotati spesso perdono la motivazione quando le lezioni sono troppo facili.",
    "s.b2-01.8": "Un apprendistato ti permette di specializzarti mentre guadagni uno stipendio.",
    "s.b2-01.9": "La sua tesi si basa su una ricerca che ha condotto per due anni.",
    "s.b2-01.10": "Il tutor ha suggerito che memorizzassimo meno e capissimo di più.",
    "s.b2-01.11": "La curiosità è la migliore motivazione per acquisire conoscenza.",
    "s.b2-01.12": "In molti paesi l'istruzione è obbligatoria fino ai diciotto anni.",
    "d.b2-01.1": "Voleva parlare delle sue opzioni per l'anno prossimo?",
    "d.b2-01.2": "Sì. Non so se continuare con un master o cercare un lavoro.",
    "d.b2-01.3": "In cosa si specializzerebbe, se continuasse?",
    "d.b2-01.4": "Ricerca educativa, probabilmente. Scrivere la tesi mi è piaciuto più di qualsiasi altra cosa.",
    "d.b2-01.5": "È un buon segno. Ha dato un'occhiata alle borse di studio?",
    "d.b2-01.6": "Un po'. Se avessi saputo prima delle scadenze, mi sarei già candidata.",
    "d.b2-01.7": "Ce n'è ancora una aperta, a condizione che presenti una proposta di ricerca entro giugno.",
    "d.b2-01.8": "Vorrei avere più tempo. Gli elaborati di questo semestre sono opprimenti.",
    "d.b2-01.9": "Allora pianifichiamo in modo che lavori alla proposta un'ora al giorno.",
    "d.b2-01.10": "Sembra fattibile. E se la borsa di studio non arrivasse?",
    "d.b2-01.11": "Allora un corso professionale o un apprendistato potrebbero essere una buona alternativa.",
    "d.b2-01.12": "Grazie. Mi sento molto meno persa adesso.",
    "m.b2-01": "Se potessi cambiare una cosa della mia istruzione, sarebbe ... . Vorrei aver ... . Se la scuola avesse offerto ..., avrei ... . Oggi credo che ... .",

