    "w.b2-02.to-hack": "hackerare",
    "w.b2-02.obsolete": "obsoleto",
    "w.b2-02.cutting-edge": "all'avanguardia",
    "p.b2-02.1": "I risultati parlano da soli.",
    "p.b2-02.2": "In teoria funziona, ma in pratica è complicato.",
    "p.b2-02.3": "È ancora in fase sperimentale.",
    "p.b2-02.4": "I dati non supportano quella conclusione.",
    "p.b2-02.5": "Nel dubbio, ripeti il test.",
    "p.b2-02.6": "La tecnologia è un'arma a doppio taglio.",
    "p.b2-02.7": "Il mio telefono è praticamente obsoleto.",
    "p.b2-02.8": "Fai un backup dei file nel caso in cui il sistema vada in crash.",
    "p.b2-02.9": "Nessuno avrebbe potuto prevederlo.",
    "p.b2-02.10": "Gli scienziati sono sull'orlo di una svolta.",
    "p.b2-02.11": "Purché sia sicuro, non mi dispiace usarlo.",
    "s.b2-02.1": "Se scaldi l'acqua a cento gradi, bolle.",
    "s.b2-02.2": "Se l'esperimento riesce, il team pubblicherà i dati l'anno prossimo.",
    "s.b2-02.3": "Se gli scienziati avessero più fondi, condurrebbero più esperimenti.",
    "s.b2-02.4": "Se il satellite non fosse stato lanciato, non avremmo osservato il fenomeno.",
    "s.b2-02.5": "A meno che l'algoritmo non sia preciso, le previsioni sono inutili.",
    "s.b2-02.6": "Se l'ipotesi fosse stata dimostrata, avrebbe cambiato completamente la teoria.",
    "s.b2-02.7": "L'intelligenza artificiale può analizzare i dati più velocemente di qualsiasi essere umano.",
    "s.b2-02.8": "La svolta nella ricerca genetica è avvenuta in un piccolo laboratorio.",
    "s.b2-02.9": "Se gli hacker fossero entrati nel sistema, milioni di account sarebbero a rischio.",
    "s.b2-02.10": "L'automazione renderà obsoleti molti lavori entro un decennio.",
    "s.b2-02.11": "Gli scienziati hanno misurato le particelle con strumenti all'avanguardia.",
    "s.b2-02.12": "Se fossi uno scienziato, studierei come le cellule si riparano da sole.",
    "d.b2-02.1": "Dottor Adler, il suo team ha annunciato una svolta la settimana scorsa. Cosa avete scoperto esattamente?",
    "d.b2-02.2": "Abbiamo sviluppato un algoritmo che prevede come certe cellule reagiscono a nuovi farmaci.",
    "d.b2-02.3": "Quanto è preciso?",
    "d.b2-02.4": "Nei nostri esperimenti, circa il novanta percento. Se i dati sono buoni, le previsioni sono affidabili.",
    "d.b2-02.5": "Cosa succederebbe se un ospedale ci facesse affidamento e si sbagliasse?",
    "d.b2-02.6": "Ecco perché i medici prenderanno sempre la decisione finale. Lo strumento li supporta soltanto.",
    "d.b2-02.7": "Alcuni temono che l'intelligenza artificiale renderà obsoleti gli scienziati.",
    "d.b2-02.8": "Se fosse vero, avremmo smesso di assumere ricercatori. Invece ne abbiamo assunti altri dieci.",
    "d.b2-02.9": "E la sicurezza informatica? I dati dei pazienti sono sensibili.",
    "d.b2-02.10": "A meno che i dati non siano criptati e conservati localmente, non li usiamo.",
    "d.b2-02.11": "Cosa c'è in programma per il laboratorio?",
    "d.b2-02.12": "Se otteniamo i fondi, condurremo uno studio più ampio la prossima primavera.",
    "m.b2-02": "Un'invenzione che ha cambiato il mondo è ... . È stata sviluppata da ... nel ... . Se non fosse stata inventata, ... . Oggi viene usata per ... . In futuro, se ..., potrebbe ... .",

