    "w.b2-03.efficiency": "l'efficienza",
    "p.b2-03.1": "Gli affari vanno a gonfie vele.",
    "p.b2-03.2": "Stiamo lavorando in perdita.",
    "p.b2-03.3": "I prezzi sono andati alle stelle.",
    "p.b2-03.4": "Veniamo al sodo.",
    "p.b2-03.5": "L'azienda è andata in bancarotta l'anno scorso.",
    "p.b2-03.6": "Al momento la domanda supera l'offerta.",
    "p.b2-03.7": "È un investimento rischioso, ma i rendimenti potrebbero essere alti.",
    "p.b2-03.8": "Da un lato..., dall'altro...",
    "p.b2-03.9": "Dobbiamo tagliare i costi su tutta la linea.",
    "p.b2-03.10": "L'affare è saltato all'ultimo minuto.",
    "p.b2-03.11": "A lungo termine, ne varrà la pena.",
    "p.b2-03.12": "La nostra quota di mercato è raddoppiata.",
    "s.b2-03.1": "L'inflazione è aumentata bruscamente; di conseguenza, i consumatori hanno speso meno.",
    "s.b2-03.2": "La startup ha lanciato un nuovo marchio; tuttavia, le vendite sono rimaste basse.",
    "s.b2-03.3": "Sebbene l'economia stia crescendo, molte famiglie fanno ancora fatica.",
    "s.b2-03.4": "La fusione ridurrà i costi; inoltre, migliorerà l'efficienza.",
    "s.b2-03.5": "Prima di tutto, abbiamo bisogno di investitori; in secondo luogo, di un bilancio realistico.",
    "s.b2-03.6": "Il paese esporta tecnologia, mentre importa la maggior parte del suo cibo.",
    "s.b2-03.7": "Nonostante la recessione, l'azienda ha realizzato un piccolo profitto.",
    "s.b2-03.8": "La previsione indica una crescita lenta; perciò dovremmo espanderci con cautela.",
    "s.b2-03.9": "I prezzi delle azioni sono crollati dopo la bancarotta del maggiore fornitore.",
    "s.b2-03.10": "La concorrenza mantiene bassi i prezzi, il che alla fine avvantaggia i consumatori.",
    "s.b2-03.11": "L'imprenditrice ha finanziato il progetto con i propri risparmi.",
    "s.b2-03.12": "Infine, ricordate che ogni affare comporta qualche rischio.",
    "d.b2-03.1": "Grazie per il suo tempo. La nostra startup produce imballaggi riutilizzabili per ristoranti.",
    "d.b2-03.2": "Interessante. Com'è la domanda?",
    "d.b2-03.3": "Forte e in crescita. Prima di tutto, le nuove normative vietano la plastica monouso; in secondo luogo, i consumatori preferiscono i marchi sostenibili.",
    "d.b2-03.4": "Tuttavia, i vostri costi di produzione sembrano alti. Come farete profitto?",
    "d.b2-03.5": "All'inizio lavoreremo con una piccola perdita. Appena ci espanderemo, l'efficienza migliorerà e i costi scenderanno.",
    "d.b2-03.6": "E la concorrenza? Ci sono aziende più grandi in questo mercato.",
    "d.b2-03.7": "Vero, ma loro importano i loro prodotti, mentre noi produciamo localmente e consegniamo più in fretta.",
    "d.b2-03.8": "Quanto finanziamento cercate?",
    "d.b2-03.9": "Due milioni, in cambio del quindici percento delle azioni.",
    "d.b2-03.10": "È ambizioso. Inoltre, la previsione presuppone nessuna recessione.",
    "d.b2-03.11": "Abbiamo preparato un secondo bilancio per un'economia più lenta. Eccolo.",
    "d.b2-03.12": "Bene. Mi mandi il piano completo e ne parliamo la settimana prossima.",
    "m.b2-03": "L'economia di ... è attualmente ... . Prima di tutto, ... . Di conseguenza, ... . Tuttavia, ... . Inoltre, ... . Perciò, a lungo termine ... .",

