    "w.b2-04.playwright": "il drammaturgo",
    "w.b2-04.tragedy": "la tragedia",
    "p.b2-04.1": "È aperto all'interpretazione.",
    "p.b2-04.2": "Il romanzo è stato subito un bestseller.",
    "p.b2-04.3": "Non riuscivo a staccarmi dal libro.",
    "p.b2-04.4": "Il dipinto mi ha lasciato un'impressione profonda.",
    "p.b2-04.5": "La melodia mi è rimasta in testa per giorni.",
    "p.b2-04.6": "Ha un'immaginazione vivida.",
    "p.b2-04.7": "La mostra merita davvero una visita.",
    "p.b2-04.8": "Cosa intende l'autore con questo?",
    "p.b2-04.9": "Il finale mi ha colto completamente di sorpresa.",
    "p.b2-04.10": "L'arte è una questione di gusti.",
    "p.b2-04.11": "Il testo è più importante della musica.",
    "s.b2-04.1": "La pubblicazione del suo primo romanzo le ha cambiato la vita.",
    "s.b2-04.2": "La raffigurazione della povertà nel film è dolorosamente realistica.",
    "s.b2-04.3": "L'interpretazione della scultura da parte del curatore ha sorpreso molti visitatori.",
    "s.b2-04.4": "La solitudine del protagonista è il tema centrale del romanzo.",
    "s.b2-04.5": "La composizione della sinfonia è costata al compositore quasi un decennio.",
    "s.b2-04.6": "Il poeta usa il mare come metafora della memoria.",
    "s.b2-04.7": "L'arrivo del direttore d'orchestra sul palco è stato accolto da un forte applauso.",
    "s.b2-04.8": "L'arte astratta richiede la partecipazione attiva dello spettatore.",
    "s.b2-04.9": "L'inaffidabilità del narratore dà alla storia la sua tensione.",
    "s.b2-04.10": "Il ritratto rivela la tristezza dietro il sorriso del re.",
    "s.b2-04.11": "Il drammaturgo ha trovato ispirazione in un'antica tragedia greca.",
    "s.b2-04.12": "La decisione della galleria di esporre giovani artisti è stata ampiamente lodata.",
    "d.b2-04.1": "Allora, cosa ne pensate tutti del romanzo?",
    "d.b2-04.2": "Onestamente, ho trovato il protagonista difficile da amare, ma la scrittura è bellissima.",
    "d.b2-04.3": "Sono d'accordo sulla scrittura. L'uso della metafora da parte dell'autrice è notevole.",
    "d.b2-04.4": "Il fiume che continua a tornare, per esempio. È una metafora del tempo?",
    "d.b2-04.5": "Questa è un'interpretazione. Io l'ho letto come il senso di colpa del narratore.",
    "d.b2-04.6": "Interessante. Il tema della colpa attraversa davvero tutto il libro.",
    "d.b2-04.7": "Sapevi che lo stanno adattando per il teatro con un drammaturgo famoso?",
    "d.b2-04.8": "Davvero? Mi chiedo come raffigureranno le scene dei sogni.",
    "d.b2-04.9": "Probabilmente con la musica. L'autrice ha detto che per lei il ritmo era più importante della trama.",
    "d.b2-04.10": "Questo spiega perché a tratti si legge come poesia.",
    "d.b2-04.11": "Scegliamo qualcosa di più leggero per il mese prossimo?",
    "d.b2-04.12": "Sì, per favore. Una commedia, o almeno non un'altra tragedia.",
    "m.b2-04": "La mostra offre una rara raffigurazione di ... . La scelta del curatore di ... crea ... . Di particolare interesse è ... . La combinazione di ... e ... produce ... . Nel complesso, ... .",

