    "w.b2-05.entitled": "avente diritto",
    "w.b2-05.discrimination": "la discriminazione",
    "w.b2-05.privacy": "la privacy",
    "w.b2-05.investigation": "l'indagine",
    "p.b2-05.1": "Innocente fino a prova contraria.",
    "p.b2-05.2": "Ha negato tutte le accuse.",
    "p.b2-05.3": "La giuria ha raggiunto un verdetto.",
    "p.b2-05.4": "Ti porterò in tribunale.",
    "p.b2-05.5": "È stata multata per aver parcheggiato illegalmente.",
    "p.b2-05.6": "Tutti sono uguali davanti alla legge.",
    "p.b2-05.7": "Il caso è stato archiviato per mancanza di prove.",
    "p.b2-05.8": "Ma è legale?",
    "p.b2-05.9": "L'avvocato ha esortato il suo cliente a restare in silenzio.",
    "p.b2-05.10": "Ha il diritto di rimanere in silenzio.",
    "p.b2-05.11": "L'imputato è stato dichiarato non colpevole.",
    "s.b2-05.1": "L'imputato ha sostenuto di essere stato a casa quella notte.",
    "s.b2-05.2": "La testimone ha ammesso di non aver visto il volto dell'uomo.",
    "s.b2-05.3": "Il giudice ha chiesto alla testimone se riconoscesse l'imputato.",
    "s.b2-05.4": "L'avvocato ha insistito che il suo cliente era innocente della frode.",
    "s.b2-05.5": "La polizia ha avvertito i residenti di non lasciare le porte aperte.",
    "s.b2-05.6": "L'azienda è stata citata in giudizio per aver violato le norme sulla privacy.",
    "s.b2-05.7": "Il ministro ha negato che la nuova legislazione avrebbe limitato dei diritti.",
    "s.b2-05.8": "Il tribunale ha stabilito che il divieto della protesta era incostituzionale.",
    "s.b2-05.9": "Dopo il verdetto, l'imputato ha annunciato che avrebbe fatto ricorso.",
    "s.b2-05.10": "Ogni cittadino ha diritto a un processo equo secondo la costituzione.",
    "s.b2-05.11": "L'indagine ha rivelato prove di discriminazione contro i lavoratori più anziani.",
    "s.b2-05.12": "Il cronista ha detto che l'uomo era stato condannato per un grave crimine.",
    "d.b2-05.1": "Noa, eri in aula stamattina. Cosa è successo?",
    "d.b2-05.2": "Il processo è iniziato con l'accusa che ha presentato nuove prove contro l'imputato.",
    "d.b2-05.3": "Cosa ha detto l'imputato?",
    "d.b2-05.4": "Ha insistito di essere innocente e ha sostenuto che i documenti erano stati falsificati.",
    "d.b2-05.5": "Qualche testimone ha deposto?",
    "d.b2-05.6": "Sì. Un'ex dipendente ha ammesso di aver firmato i contratti senza leggerli.",
    "d.b2-05.7": "Come ha reagito il giudice?",
    "d.b2-05.8": "Ha avvertito entrambe le parti di non parlare con la stampa e ha chiesto se sarebbero state presentate altre prove.",
    "d.b2-05.9": "Si aspetta un verdetto a breve?",
    "d.b2-05.10": "Gli avvocati mi hanno detto che il processo probabilmente durerà altre tre settimane.",
    "d.b2-05.11": "E se viene condannato per frode?",
    "d.b2-05.12": "Il suo avvocato ha già annunciato che farebbero ricorso.",
    "m.b2-05": "Il processo a ... è iniziato il ... . L'imputato ha negato ... e ha sostenuto che ... . Un testimone ha ammesso che ... . Il giudice ha avvertito ... . L'avvocato ha insistito che ... e ha annunciato che ... .",

