    "w.b2-06.to-spread": "diffondersi",
    "w.b2-06.access": "l'accesso",
    "w.b2-06.infrastructure": "l'infrastruttura",
    "w.b2-06.charity": "l'associazione benefica",
    "w.b2-06.to-donate": "donare",
    "w.b2-06.activist": "l'attivista",
    "w.b2-06.awareness": "la consapevolezza",
    "w.b2-06.inequality": "la disuguaglianza",
    "w.b2-06.deforestation": "la deforestazione",
    "w.b2-06.biodiversity": "la biodiversità",
    "w.b2-06.global-warming": "il riscaldamento globale",
    "w.b2-06.threat": "la minaccia",
    "w.b2-06.to-tackle": "affrontare",
    "w.b2-06.consequence": "la conseguenza",
    "w.b2-06.to-affect": "colpire",
    "w.b2-06.vulnerable": "vulnerabile",
    "w.b2-06.to-flee": "fuggire",
    "p.b2-06.1": "È un problema globale che richiede una soluzione globale.",
    "p.b2-06.2": "Dobbiamo sensibilizzare l'opinione pubblica.",
    "p.b2-06.3": "Milioni di persone non hanno accesso all'acqua pulita.",
    "p.b2-06.4": "Pensare globalmente, agire localmente.",
    "p.b2-06.5": "Il divario tra ricchi e poveri si sta allargando.",
    "p.b2-06.6": "Il tempo sta per scadere.",
    "p.b2-06.7": "Ogni donazione conta, per quanto piccola.",
    "p.b2-06.8": "I colloqui si sono conclusi senza un accordo.",
    "p.b2-06.9": "È una goccia nel mare.",
    "p.b2-06.10": "Non possiamo permetterci di ignorarlo.",
    "p.b2-06.11": "Prevenire è meglio che curare.",
    "s.b2-06.1": "Di fronte a una grave siccità, il governo ha chiesto aiuti umanitari.",
    "s.b2-06.2": "Firmato nel 2015, il trattato mira a limitare il riscaldamento globale.",
    "s.b2-06.3": "Donare a un'associazione benefica è un modo per affrontare la disuguaglianza.",
    "s.b2-06.4": "Essendo fuggite dal conflitto, le famiglie vivono ora in rifugi temporanei.",
    "s.b2-06.5": "La deforestazione distrugge la biodiversità, colpendo milioni di specie.",
    "s.b2-06.6": "Le sanzioni imposte l'anno scorso hanno avuto gravi conseguenze.",
    "s.b2-06.7": "Diffondendosi rapidamente oltre i confini, la pandemia ha colpito ogni paese.",
    "s.b2-06.8": "Gli attivisti sperano che sensibilizzare l'opinione pubblica porti a un vero cambiamento.",
    "s.b2-06.9": "L'ambasciatore ha avvertito che la diplomazia da sola non avrebbe posto fine al conflitto.",
    "s.b2-06.10": "Migliorare le infrastrutture è essenziale per lo sviluppo delle regioni povere.",
    "s.b2-06.11": "Le popolazioni vulnerabili soffrono di più gli effetti della globalizzazione.",
    "s.b2-06.12": "Senza accesso all'istruzione, i bambini restano intrappolati nella povertà.",
    "d.b2-06.1": "Dottor Mansour, quanto è seria oggi la minaccia del riscaldamento globale?",
    "d.b2-06.2": "Estremamente seria. Avendo studiato i dati per vent'anni, posso dire che i cambiamenti sono più rapidi del previsto.",
    "d.b2-06.3": "Yonatan, la sua organizzazione si concentra sulla deforestazione. Perché?",
    "d.b2-06.4": "Perché abbattere le foreste distrugge la biodiversità e allo stesso tempo rilascia carbonio.",
    "d.b2-06.5": "Cosa possono fare le persone comuni?",
    "d.b2-06.6": "Donare aiuta, ma sensibilizzare e votare per le politiche giuste conta di più.",
    "d.b2-06.7": "Sono d'accordo. I governi rispondono alla pressione, come abbiamo visto con il trattato firmato l'anno scorso.",
    "d.b2-06.8": "Alcuni sostengono che le sanzioni ai paesi inquinanti sarebbero più efficaci.",
    "d.b2-06.9": "Imporre sanzioni senza offrire aiuti di solito danneggia le popolazioni più vulnerabili.",
    "d.b2-06.10": "Esatto. Diplomazia e sviluppo devono andare insieme.",
    "d.b2-06.11": "C'è qualche motivo di speranza?",
    "d.b2-06.12": "Sì. L'energia rinnovabile si sta diffondendo più velocemente di quanto chiunque si aspettasse dieci anni fa.",
    "m.b2-06": "Avendo identificato ... come una grave minaccia, proponiamo ... . Finanziato da ..., il progetto ... . Lavorando con le comunità locali, puntiamo a ... . Ridurre ... inoltre ... .",

