    "w.c1-01.contradiction": "la contraddizione",
    "w.c1-01.to-assume": "supporre",
    "w.c1-01.stance": "la posizione",
    "w.c1-01.controversial": "controverso",
    "w.c1-01.to-undermine": "minare",
    "w.c1-01.to-acknowledge": "riconoscere",
    "w.c1-01.to-advocate": "promuovere",
    "w.c1-01.opponent": "l'avversario",
    "w.c1-01.consensus": "il consenso",
    "w.c1-01.debate": "il dibattito",
    "w.c1-01.to-outweigh": "prevalere su",
    "w.c1-01.nevertheless": "ciononostante",
    "w.c1-01.whereas": "laddove",
    "p.c1-01.1": "È un'osservazione giusta, ma perde di vista il quadro generale.",
    "p.c1-01.2": "Bisogna ammettere che le prove sono limitate.",
    "p.c1-01.3": "Lasciatemi fare l'avvocato del diavolo per un momento.",
    "p.c1-01.4": "Capisco il tuo punto, ma non sono convinto.",
    "p.c1-01.5": "Correlazione non implica causalità.",
    "p.c1-01.6": "Ti stai contraddicendo.",
    "p.c1-01.7": "Accettiamo di non essere d'accordo.",
    "p.c1-01.8": "L'onere della prova spetta a te.",
    "p.c1-01.9": "Quell'argomento semplicemente non sta in piedi.",
    "p.c1-01.10": "Con tutto il rispetto, questo non c'entra.",
    "p.c1-01.11": "Ciò che conta qui è l'effetto a lungo termine.",
    "p.c1-01.12": "Tutto considerato, i benefici superano i costi.",
    "s.c1-01.1": "Sebbene la sua affermazione suoni persuasiva, la premessa alla base è falsa.",
    "s.c1-01.2": "Certo, la politica è controversa; ciononostante, ha ridotto la povertà.",
    "s.c1-01.3": "È la mancanza di prove che mina tutta la sua argomentazione.",
    "s.c1-01.4": "Ammetto quel punto, laddove la conclusione continuo a respingerla.",
    "s.c1-01.5": "Una posizione coerente riconosce le controargomentazioni invece di ignorarle.",
    "s.c1-01.6": "Anche se supponiamo buone intenzioni, il bias influenza ogni decisione.",
    "s.c1-01.7": "Ciò che rende pericolosa una fallacia è che sembra logica.",
    "s.c1-01.8": "Ha confutato l'affermazione dell'avversario con una sola statistica.",
    "s.c1-01.9": "Promuovere il cambiamento è facile; giustificarne i costi è più difficile.",
    "s.c1-01.10": "C'è una chiara contraddizione tra la sua premessa e la sua conclusione.",
    "s.c1-01.11": "Il consenso scientifico non significa che il dibattito sia chiuso per sempre.",
    "s.c1-01.12": "Al contrario, i dati rafforzano l'affermazione invece di indebolirla.",
    "d.c1-01.1": "Omri, tu sostieni il voto obbligatorio. La tua affermazione iniziale, per favore.",
    "d.c1-01.2": "La democrazia dipende dalla partecipazione. Quando metà della popolazione resta a casa, il risultato riflette un campione distorto, non la volontà pubblica.",
    "d.c1-01.3": "Leah, la tua risposta.",
    "d.c1-01.4": "Bisogna ammettere che la bassa affluenza è un problema. Ciononostante, costringere le persone a votare mina proprio la libertà che le elezioni dovrebbero proteggere.",
    "d.c1-01.5": "Ammetto che la libertà conta. Tuttavia, accettiamo già tasse obbligatorie e il dovere di giurato, laddove votare richiede dieci minuti.",
    "d.c1-01.6": "È un confronto falso. Le tasse finanziano servizi; un voto forzato produce scelte casuali da parte di elettori non informati.",
    "d.c1-01.7": "Omri, come rispondi alla controargomentazione sugli elettori non informati?",
    "d.c1-01.8": "Ciò che mostrano i dati dall'Australia è che il voto obbligatorio in realtà aumenta la conoscenza politica nel tempo.",
    "d.c1-01.9": "Un solo paese non è certo un consenso. Inoltre, stai supponendo che l'effetto sarebbe lo stesso qui.",
    "d.c1-01.10": "Certo, ma l'alternativa, non fare nulla, ha chiaramente fallito.",
    "d.c1-01.11": "Dichiarazioni finali. Prima Leah.",
    "d.c1-01.12": "Tutto considerato, i costi per la libertà superano i benefici incerti. Convincete le persone a votare; non costringetele.",
    "m.c1-01": "Si sostiene spesso che ... . Bisogna ammettere che ... . Ciononostante, ciò che mostrano i dati è che ... . Laddove gli oppositori sostengono ..., questo trascura ... . Tutto considerato, ... .",

    "w.c1-02.cognitive": "cognitivo",
    "w.c1-02.perception": "la percezione",
