    "w.c1-02.resilience": "la resilienza",
    "w.c1-02.self-esteem": "l'autostima",
    "w.c1-02.reward": "la ricompensa",
    "w.c1-02.incentive": "l'incentivo",
    "w.c1-02.prejudice": "il pregiudizio",
    "w.c1-02.stereotype": "lo stereotipo",
    "w.c1-02.peer-pressure": "la pressione del gruppo",
    "w.c1-02.manipulation": "la manipolazione",
    "w.c1-02.procrastination": "la procrastinazione",
    "w.c1-02.mindset": "la mentalità",
    "w.c1-02.therapy": "la terapia",
    "w.c1-02.willpower": "la forza di volontà",
    "w.c1-02.to-repress": "reprimere",
    "w.c1-02.rational": "razionale",
    "p.c1-02.1": "È tutto nella tua testa.",
    "p.c1-02.2": "Le vecchie abitudini sono dure a morire.",
    "p.c1-02.3": "Tende a pensare troppo alle cose.",
    "p.c1-02.4": "Presumibilmente, lo stress ha avuto un ruolo.",
    "p.c1-02.5": "Deve essere stato sotto una pressione enorme.",
    "p.c1-02.6": "In una certa misura, siamo tutti di parte.",
    "p.c1-02.7": "Non ho resistito alla tentazione.",
    "p.c1-02.8": "Sembra che le ricompense funzionino meglio delle punizioni.",
    "p.c1-02.9": "Non saltare alle conclusioni.",
    "p.c1-02.10": "Si può sostenere che la personalità sia plasmata più dall'ambiente che dai geni.",
    "p.c1-02.11": "Non potevi saperlo in quel momento.",
    "s.c1-02.1": "Le persone con alta autostima potrebbero gestire meglio le critiche.",
    "s.c1-02.2": "La procrastinazione sembra essere legata all'ansia piuttosto che alla pigrizia.",
    "s.c1-02.3": "Le persone estroverse tendono a cercare ricompense nelle situazioni sociali.",
    "s.c1-02.4": "Il soggetto potrebbe aver represso il ricordo per anni.",
    "s.c1-02.5": "La pressione del gruppo potrebbe spiegare, in una certa misura, perché gli adolescenti corrono rischi.",
    "s.c1-02.6": "La nostra percezione è, si può sostenere, plasmata da pregiudizi subconsci.",
    "s.c1-02.7": "Gli incentivi presumibilmente funzionano solo quando l'obiettivo sembra raggiungibile.",
    "s.c1-02.8": "La resilienza sembra dipendere in parte dalle prime relazioni.",
    "s.c1-02.9": "Non può aver agito d'impulso; il piano era troppo dettagliato.",
    "s.c1-02.10": "La terapia può aiutare i pazienti a riconoscere la manipolazione nelle loro relazioni.",
    "s.c1-02.11": "L'intuizione non è sempre irrazionale; spesso riflette l'esperienza.",
    "s.c1-02.12": "Una mentalità di crescita a quanto pare migliora le prestazioni cognitive nei bambini.",
    "d.c1-02.1": "Dottoressa Peretz, perché le persone intelligenti prendono decisioni irrazionali?",
    "d.c1-02.2": "Intelligenza e razionalità sono tratti diversi. Le persone intelligenti potrebbero semplicemente essere più brave a giustificare i propri impulsi.",
    "d.c1-02.3": "Quindi la forza di volontà non è la risposta?",
    "d.c1-02.4": "Solo in una certa misura. La forza di volontà tende a esaurirsi; un ambiente di sostegno sembra contare di più.",
    "d.c1-02.5": "La sua ricerca sulla procrastinazione ha sorpreso molte persone.",
    "d.c1-02.6": "Presumibilmente perché supponiamo che i procrastinatori siano pigri. I nostri dati suggeriscono che spesso sono perfezionisti ansiosi.",
    "d.c1-02.7": "I social media potrebbero peggiorare la situazione?",
    "d.c1-02.8": "Potrebbero. Il confronto costante sembra abbassare l'autostima, soprattutto tra gli adolescenti esposti alla pressione del gruppo.",
    "d.c1-02.9": "C'è qualcosa che costruisce la resilienza in modo affidabile?",
    "d.c1-02.10": "Si può sostenere che sia l'empatia di un adulto di fiducia. Le prove non sono conclusive, ma sono coerenti.",
    "d.c1-02.11": "Un ultimo consiglio per i nostri lettori?",
    "d.c1-02.12": "Trattate la vostra intuizione come un'ipotesi, non come un verdetto. Poi verificatela.",
    "m.c1-02": "La ricerca suggerisce che ... tende a ... . Questo potrebbe essere perché ... . In una certa misura, ... . Sembra che ..., anche se le prove sono ... . Presumibilmente, ... .",

    "w.c1-03.empire": "l'impero",
    "w.c1-03.revolution": "la rivoluzione",
