    "w.c1-03.paradox": "il paradosso",
    "w.c1-03.to-interpret": "interpretare",
    "w.c1-03.turning-point": "il punto di svolta",
    "p.c1-03.1": "La storia si ripete.",
    "p.c1-03.2": "Chi dimentica il passato è condannato a ripeterlo.",
    "p.c1-03.3": "Ha segnato un punto di svolta nella storia europea.",
    "p.c1-03.4": "Col senno di poi, il crollo era inevitabile.",
    "p.c1-03.5": "Il fine giustifica i mezzi, o no?",
    "p.c1-03.6": "Penso, dunque sono.",
    "p.c1-03.7": "Conosci te stesso.",
    "p.c1-03.8": "Questo solleva più domande di quante ne risolva.",
    "p.c1-03.9": "La storia è scritta dai vincitori.",
    "p.c1-03.10": "Non solo l'impero cadde, ma scomparve anche la sua lingua.",
    "p.c1-03.11": "Esiste davvero il libero arbitrio?",
    "s.c1-03.1": "Mai prima un impero era crollato così rapidamente e così completamente.",
    "s.c1-03.2": "Non solo la rivoluzione pose fine alla schiavitù, ma ridefinì anche la cittadinanza.",
    "s.c1-03.3": "Poiché gli archivi furono distrutti, gli storici devono interpretare frammenti.",
    "s.c1-03.4": "Solo dopo l'indipendenza il paese cominciò a scrivere la propria storia.",
    "s.c1-03.5": "I filosofi antichi si chiedevano se la virtù potesse essere insegnata.",
    "s.c1-03.6": "Sebbene la ragione guidi l'etica, è spesso l'emozione a decidere la nostra morale.",
    "s.c1-03.7": "Se il re non fosse stato rovesciato, l'era degli imperi sarebbe forse continuata.",
    "s.c1-03.8": "Lo scetticismo, lungi dal negare la conoscenza, chiede come la giustifichiamo.",
    "s.c1-03.9": "Tanto potente era l'ideologia che milioni la accettarono senza discutere.",
    "s.c1-03.10": "Il paradosso del libero arbitrio è che ci sentiamo liberi eppure agiamo in modo prevedibile.",
    "s.c1-03.11": "Ogni civiltà che conquistò i suoi vicini affrontò infine lo stesso destino.",
    "s.c1-03.12": "Ciò che i filosofi chiamano esistenza, gli storici lo chiamano contesto.",
    "d.c1-03.1": "Perché crollò l'Impero romano? Shai, cominciamo da te.",
    "d.c1-03.2": "Tradizionalmente, gli storici incolpavano le invasioni. Non solo i confini erano troppo lunghi, ma anche l'esercito era esausto.",
    "d.c1-03.3": "Mor, non sei d'accordo?",
    "d.c1-03.4": "In parte. Se l'economia fosse stata sana, l'impero avrebbe potuto sopravvivere alle invasioni, come aveva fatto in passato.",
    "d.c1-03.5": "Quindi interpreti il crollo come economico piuttosto che militare?",
    "d.c1-03.6": "Sì. La schiavitù rendeva inutile l'innovazione, e quando le conquiste si fermarono, si fermò anche l'afflusso di schiavi.",
    "d.c1-03.7": "Però è una lettura moderna. Gli stessi scrittori antichi incolpavano una perdita di virtù.",
    "d.c1-03.8": "Il che solleva una domanda filosofica: una civiltà può decadere moralmente?",
    "d.c1-03.9": "Solo se supponiamo che la morale sia più di un'ideologia, cosa che gli scettici negherebbero.",
    "d.c1-03.10": "Eppure senza un'etica condivisa, nessuna società resta unita a lungo.",
    "d.c1-03.11": "Eccellente. Per la settimana prossima, leggete le fonti d'archivio e decidete quale punto di svolta trovate più convincente.",
    "d.c1-03.12": "E se la caduta fu inevitabile, o se il libero arbitrio ebbe un ruolo.",
    "m.c1-03": "Raramente una domanda ha diviso i pensatori così profondamente come ... . Laddove alcuni sostengono che ..., altri ritengono che ... . Non solo questo è importante per ..., ma anche ... . Solo ... possiamo ... .",

