    "w.c1-04.to-clarify": "chiarire",
    "w.c1-04.scope": "l'ambito",
    "w.c1-04.implication": "l'implicazione",
    "w.c1-04.to-convey": "veicolare",
    "p.c1-04.1": "In allegato trova la bozza riveduta.",
    "p.c1-04.2": "Scrivo in riferimento alla sua email del 3 maggio.",
    "p.c1-04.3": "I risultati sono riassunti nella Tabella 2.",
    "p.c1-04.4": "Come indicato sopra, il campione era piccolo.",
    "p.c1-04.5": "Questo esula dall'ambito del presente studio.",
    "p.c1-04.6": "Sono necessarie ulteriori ricerche.",
    "p.c1-04.7": "Qualora necessitasse di ulteriori informazioni, non esiti a contattarmi.",
    "p.c1-04.8": "In conclusione, le prove suggeriscono che...",
    "p.c1-04.9": "Potrebbe chiarire cosa intende con questo termine?",
    "p.c1-04.10": "La scadenza per la consegna è il 30 giugno.",
    "p.c1-04.11": "È stato sostenuto che...",
    "p.c1-04.12": "Resto in attesa del suo riscontro.",
    "s.c1-04.1": "È ampiamente sostenuto che una terminologia chiara migliori la coesione.",
    "s.c1-04.2": "I dati sono stati analizzati con la metodologia descritta nell'appendice.",
    "s.c1-04.3": "I risultati indicano un forte legame tra sonno e memoria.",
    "s.c1-04.4": "Le fonti devono essere citate correttamente per evitare il plagio.",
    "s.c1-04.5": "La proposta è stata presentata prima della scadenza; di conseguenza, è stata esaminata per prima.",
    "s.c1-04.6": "Una frase ambigua dovrebbe essere riscritta piuttosto che spiegata.",
    "s.c1-04.7": "Inoltre, le implicazioni di questi risultati vanno oltre l'istruzione.",
    "s.c1-04.8": "Una scaletta concisa viene preparata prima che la prima bozza sia scritta.",
    "s.c1-04.9": "Il promemoria chiarisce l'ambito del progetto per tutti i reparti.",
    "s.c1-04.10": "Parafrasare veicola l'idea dell'autore senza copiarne la formulazione.",
    "s.c1-04.11": "Un'attenta correzione di bozze è considerata essenziale prima della consegna.",
    "s.c1-04.12": "La bibliografia elenca ogni fonte citata nella tesi.",
    "d.c1-04.1": "Nir, ho letto la tua bozza. La sezione sulla metodologia è solida, ma l'introduzione è troppo lunga.",
    "d.c1-04.2": "Lo temevo. Dovrei spostare il contesto in un'appendice?",
    "d.c1-04.3": "In parte. Riassumi la storia in un paragrafo e cita le fonti principali invece di descriverle.",
    "d.c1-04.4": "Capito. E il capitolo sui risultati?",
    "d.c1-04.5": "I dati sono presentati bene, ma diverse frasi sono ambigue. Per esempio, qui la parola significativo non è chiara.",
    "d.c1-04.6": "Significatività statistica. Chiarirò la terminologia.",
    "d.c1-04.7": "Bene. Inoltre, la sezione sulle implicazioni fa affermazioni che vanno oltre l'ambito dei tuoi dati.",
    "d.c1-04.8": "Intende la parte sulla politica nazionale?",
    "d.c1-04.9": "Esatto. O attenua quelle affermazioni o toglile. Di' cosa indicano i risultati, non cosa speri che dimostrino.",
    "d.c1-04.10": "Parafraserò la sezione e abbasserò i toni. Altro?",
    "d.c1-04.11": "Controlla la bibliografia; mancano due fonti citate nel capitolo tre. Poi rileggi tutto prima di consegnare.",
    "d.c1-04.12": "Grazie. Le invierò una bozza riveduta entro venerdì.",
    "m.c1-04": "Questo studio esamina ... . I dati sono stati raccolti da ... e analizzati con ... . I risultati indicano che ... . Inoltre, ... . Di conseguenza, si suggerisce che ... . Vengono discusse le implicazioni per ... .",

