    "w.c2-01.once-in-a-blue-moon": "ogni morte di papa",
    "w.c2-01.hit-the-nail-on-the-head": "colpire nel segno",
    "w.c2-01.tip-of-the-iceberg": "la punta dell'iceberg",
    "w.c2-01.two-birds-one-stone": "prendere due piccioni con una fava",
    "w.c2-01.sit-on-the-fence": "non prendere posizione",
    "w.c2-01.pinch-of-salt": "prendere qualcosa con le pinze",
    "w.c2-01.read-between-the-lines": "leggere tra le righe",
    "p.c2-01.1": "Le sarei molto grato se potesse...",
    "p.c2-01.2": "Mi dai una mano?",
    "p.c2-01.3": "È venuto a mancare la primavera scorsa.",
    "p.c2-01.4": "Non ci vuole un genio.",
    "p.c2-01.5": "Non giriamoci intorno.",
    "p.c2-01.6": "È stata una mezza delusione, per usare un eufemismo.",
    "p.c2-01.7": "Siamo spiacenti di informarla che...",
    "p.c2-01.8": "Senza offesa, ma non è il tuo punto forte.",
    "p.c2-01.9": "Ha il dono della parola.",
    "p.c2-01.10": "Al momento sono tra un lavoro e l'altro.",
    "p.c2-01.11": "È dire poco.",
    "p.c2-01.12": "Da quanto tempo!",
    "s.c2-01.1": "In un registro formale, raramente usiamo slang o forme contratte.",
    "s.c2-01.2": "La sua risposta è stata piena di tatto, ma l'allusione era impossibile da non cogliere.",
    "s.c2-01.3": "È stato brusco riguardo ai problemi, cosa che alcuni colleghi hanno trovato scortese.",
    "s.c2-01.4": "La parola è corretta in senso letterale, eppure la sua connotazione è negativa.",
    "s.c2-01.5": "I due termini differiscono solo per sfumatura, non per significato.",
    "s.c2-01.6": "Devi leggere tra le righe di questa email.",
    "s.c2-01.7": "Il giornalista ha coniato un'espressione che ora usano tutti.",
    "s.c2-01.8": "Chiamare i licenziamenti ristrutturazione è un classico eufemismo.",
    "s.c2-01.9": "Andiamo a teatro ogni morte di papa.",
    "s.c2-01.10": "Prendi le sue promesse con le pinze.",
    "s.c2-01.11": "Dalla formulazione della lettera ho dedotto che avevano rifiutato.",
    "s.c2-01.12": "Le cifre riportate sono solo la punta dell'iceberg.",
    "d.c2-01.1": "Ho preparato la bozza del suo discorso per la riunione del personale. Rivediamo il registro?",
    "d.c2-01.2": "Sì. Il primo paragrafo sembra troppo formale per una riunione interna.",
    "d.c2-01.3": "D'accordo. La frase d'apertura suona come un avviso legale; potremmo renderla più diretta.",
    "d.c2-01.4": "Diretta, ma non brusca. Le persone sono in ansia per la fusione.",
    "d.c2-01.5": "Allora un leggero understatement potrebbe funzionare meglio di un annuncio drammatico.",
    "d.c2-01.6": "Esatto. E per favore tolga le espressioni idiomatiche sportive. Non tutti le conoscono.",
    "d.c2-01.7": "Bene. Devo tenere quella sul leggere tra le righe?",
    "d.c2-01.8": "Sì, quella è chiara in qualsiasi lingua. Inoltre, faccia attenzione alla parola economico; ha una connotazione negativa.",
    "d.c2-01.9": "Userò invece accessibile. La sfumatura è più gentile.",
    "d.c2-01.10": "Bene. Un'altra cosa: il finale allude ai licenziamenti senza dirlo.",
    "d.c2-01.11": "Era intenzionale, un modo pieno di tatto per preparare le persone.",
    "d.c2-01.12": "Preferirei dirlo chiaramente. Gli eufemismi fanno sì che le persone si fidino meno di te, non di più.",
    "m.c2-01": "Informale: Ehi, stasera non ce la faccio, è saltato fuori un imprevisto. Formale: Mi rammarico di non poter partecipare questa sera a causa di un impegno imprevisto. La versione informale usa ..., mentre quella formale ... .",

    "w.c2-02.irony": "l'ironia",
    "w.c2-02.sarcasm": "il sarcasmo",
    "w.c2-02.satire": "la satira",
    "w.c2-02.parody": "la parodia",
    "w.c2-02.pun": "il gioco di parole",
    "w.c2-02.witty": "arguto",
    "w.c2-02.punchline": "la battuta finale",
    "w.c2-02.to-tease": "prendere in giro",
    "w.c2-02.to-mock": "deridere",
    "w.c2-02.absurd": "assurdo",
    "w.c2-02.hilarious": "esilarante",
    "w.c2-02.self-deprecating": "autoironico",
    "w.c2-02.to-exaggerate": "esagerare",
    "w.c2-02.hyperbole": "l'iperbole",
    "w.c2-02.figurative": "figurato",
    "w.c2-02.innuendo": "l'insinuazione",
    "w.c2-02.comedian": "il comico",
    "w.c2-02.sketch": "lo sketch",
    "w.c2-02.anecdote": "l'aneddoto",
    "w.c2-02.to-misinterpret": "fraintendere",
    "w.c2-02.tongue-in-cheek": "faceto",
    "w.c2-02.offensive": "offensivo",
    "w.c2-02.taboo": "il tabù",
    "w.c2-02.sense-of-humour": "il senso dell'umorismo",
    "p.c2-02.1": "Oh, fantastico, proprio quello che mi serviva.",
    "p.c2-02.2": "Ti sto solo prendendo in giro.",
    "p.c2-02.3": "Bel tempo, eh? (detto durante una tempesta)",
    "p.c2-02.4": "Dovevi esserci.",
    "p.c2-02.5": "Quella battuta è caduta nel vuoto.",
    "p.c2-02.6": "Sono quasi morto dal ridere.",
    "p.c2-02.7": "Fa ridere perché è vero.",
    "p.c2-02.8": "Non ha capito la battuta.",
    "p.c2-02.9": "Te l'ho detto un milione di volte di non esagerare.",
    "p.c2-02.10": "Non prenderlo alla lettera.",
    "p.c2-02.11": "Troppo presto?",
    "p.c2-02.12": "Beh, è andata benissimo.",
    "s.c2-02.1": "La recensione del critico era così ironica che alcuni lettori l'hanno presa sul serio.",
    "s.c2-02.2": "Il sarcasmo è difficile da individuare per iscritto senza il tono di voce.",
    "s.c2-02.3": "La satira derideva i politici di ogni partito allo stesso modo.",
    "s.c2-02.4": "Un buon gioco di parole dipende da due significati della stessa parola.",
    "s.c2-02.5": "Le battute autoironiche del comico hanno fatto sì che il pubblico lo amasse all'istante.",
    "s.c2-02.6": "Stava scherzando, ma la sua osservazione faceta è stata fraintesa.",
    "s.c2-02.7": "Dire che muoio di fame dopo una breve attesa è un'iperbole.",
    "s.c2-02.8": "Lo sketch era assurdo, eppure in qualche modo esilarante.",
    "s.c2-02.9": "Un'insinuazione permette a chi parla di suggerire qualcosa senza dichiararlo.",
    "s.c2-02.10": "Le battute su argomenti tabù possono facilmente diventare offensive.",
    "s.c2-02.11": "Il suo aneddoto sul matrimonio è finito con una battuta finale perfetta.",
    "s.c2-02.12": "Il linguaggio figurato dice una cosa e ne intende un'altra.",
    "d.c2-02.1": "Jonas, sto traducendo il tuo spettacolo e sono bloccata sulla battuta d'apertura.",
    "d.c2-02.2": "Quella sulla banca? È un gioco di parole; in inglese la stessa parola significa sia curiosità sia interessi su un prestito.",
    "d.c2-02.3": "Esattamente il mio problema. In ebraico sono due parole diverse, quindi la battuta finale sparisce.",
    "d.c2-02.4": "Puoi sostituirla con un altro gioco di parole che funzioni in ebraico?",
    "d.c2-02.5": "Probabilmente. Il pubblico non ha bisogno della stessa battuta, solo dello stesso effetto.",
    "d.c2-02.6": "Bene. E la parte sarcastica sulla mia città natale? Capiranno che sono ironico?",
    "d.c2-02.7": "Se mantengo il tuo tono, sì. Ma la battuta sul sindaco qui potrebbe risultare offensiva.",
    "d.c2-02.8": "In realtà è autoironica. Sto deridendo me stesso per averlo votato.",
    "d.c2-02.9": "Allora lo renderò più chiaro, o la gente lo fraintenderà come un attacco.",
    "d.c2-02.10": "Giusto. E l'aneddoto con la capra? È troppo assurdo?",
    "d.c2-02.11": "No, l'assurdo viaggia bene. Sono i giochi di parole e i tabù che cambiano da cultura a cultura.",
    "d.c2-02.12": "Quindi la capra resta e la banca se ne va. La comicità è un mestiere brutale.",
    "m.c2-02": "Niente dice comodità moderna come ... . Dopo solo ... ore di attesa, sono stato premiato con ... . Naturalmente, ... . Si potrebbe quasi pensare che ... .",

    "w.c2-03.rhetoric": "la retorica",
    "w.c2-03.rhetorical-question": "la domanda retorica",
