    "w.c2-03.alliteration": "l'allitterazione",
    "w.c2-03.foreshadowing": "la prefigurazione",
    "w.c2-03.climax": "il climax",
    "w.c2-03.suspense": "la suspense",
    "w.c2-03.point-of-view": "il punto di vista",
